import networkx as nx,numpy as np,random,math,json
random.seed(872)
def sc(G,typ):
 if not nx.is_biconnected(G):return -1
 n=len(G);A=nx.to_numpy_array(G,nodelist=range(n));Q=np.linalg.inv(np.diag(A.sum(1))-A+np.ones((n,n))/n)
 if typ=='bead':return Q[0,0]+Q[1,1]-2*Q[0,1]
 return max(Q[0,0]+np.diag(Q)-2*Q[0])
out=[]
for typ in ['bead','cap']:
 for n in range(10,19):
  best=-1;BG=None
  for rep in range(8):
   seq=[2]+[4]*(n-1)
   if typ=='bead':seq[1]=2
   G=nx.havel_hakimi_graph(seq)
   for trial in range(1000):
    try:nx.double_edge_swap(G,nswap=5,max_tries=100)
    except:pass
    if nx.is_biconnected(G):break
   s=sc(G,typ)
   for k in range(25000):
    (a,b),(c,d)=random.sample(list(G.edges()),2)
    if random.random()<.5:c,d=d,c
    if len({a,b,c,d})<4 or G.has_edge(a,c) or G.has_edge(b,d):continue
    G.remove_edge(a,b);G.remove_edge(c,d);G.add_edge(a,c);G.add_edge(b,d)
    ns=sc(G,typ);temp=.008*(1-k/25000)
    if ns>0 and(ns>s-1e-8 or random.random()<math.exp(min(0,(ns-s)/max(temp,1e-8)))):s=ns
    else:
     G.remove_edge(a,c);G.remove_edge(b,d);G.add_edge(a,b);G.add_edge(c,d)
    if s>best+1e-8:best=s;BG=G.copy()
  from fractions import Fraction
  rec={'type':typ,'n':n,'R':best,'frac':str(Fraction(float(best)).limit_denominator()),'gap':(n-1)/4-best if typ=='bead' else n/4-.7-best,'edges':list(BG.edges())}
  out.append(rec);print(rec,flush=True);json.dump(out,open('workspace/agent3_biconnected.json','w'))

